"""Connect the wall returns across each bevel, including the observatory setback."""
from functools import lru_cache
import numpy as np
from shapely.geometry import Polygon,LineString
from shapely.ops import unary_union
from shapely.geometry.polygon import orient
from rooftops import T, PITCH, native, WORK

@lru_cache(None)
def decks(key):
    level_count=T[key].n
    # Source tower colliders are generated by towers.py before this geometry pass.
    source=WORK/'fleet/old-mesh'/f'tower-{key}-{level_count}-col.obj'
    solids=native.read_obj(source)[1]
    return [orient(unary_union([Polygon(fp) for fp,lo,hi in solids if abs(hi-i*PITCH)<.015]).convex_hull.simplify(.003),sign=1)
            for i in range(level_count)]

def unit(v):return v/np.linalg.norm(v)

def returns(outline):
    vertices=np.asarray(outline.exterior.coords)[:-1]
    n=len(vertices)
    for i,pt in enumerate(vertices):
        a,b,c,d=[vertices[j%n] for j in (i-1,i,i+1,i+2)]
        delta=c-b; before=unit(b-a);after=unit(d-c);axis=unit(delta)
        if abs(axis[0])>.10 and abs(axis[1])>.10:
            yield np.array([b-before*.32,b,c,c+after*.32])
        elif abs(before@axis)<.1:
            yield np.array([b-before*.32,b,b+axis*.32])

def bands(key,state):
    shapes=decks(key)
    for lev,outline in enumerate(shapes[:state]):
        h=PITCH*lev
        if lev<len(shapes)-1:
            upper=shapes[lev+1]
            for path in returns(upper):yield h,3.08,path,'ceramic'
            for path in returns(outline):
                if LineString(path).distance(upper)>.20:yield h,.52,path,'ceramic'
        else:
            for path in returns(outline):yield h,.52,path,'ceramic'

def strips(path):
    directions=np.diff(path,axis=0);directions/=np.linalg.norm(directions,axis=1)[:,None]
    ns=np.column_stack([-directions[:,1],directions[:,0]])
    miters=[ns[0]]
    for n,m in zip(ns,ns[1:]):miters.append((n+m)/(1+n@m))
    miters.append(ns[-1]);m=np.asarray(miters)
    outer=path+.013*m;inner=path+.201*m
    for j in range(len(path)-1):
        yield [tuple(p) for p in [outer[j],outer[j+1],inner[j+1],inner[j]]]

def add(mesh,key,state):
    for h,height,path,finish in bands(key,state):
        for fp in strips(path):
            mesh.prism(fp,h,height,'zinc',finish,True)
